#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <algorithm>
#include <cassert>
#include <iostream>
// 물리 시간과 메뉴 시간을 분리한 정수 tick 모델.
class Clock {
    int frozen_ = 0;
    int simulation_ = 0;
    int ui_ = 0;
public:
    bool request(int ticks) {
        if (ticks < 0 || ticks > 8) return false;
        frozen_ = std::max(frozen_, ticks); // 중첩은 합산하지 않는다.
        return true;
    }
    void step() {
        ++ui_;
        if (frozen_ > 0) --frozen_;
        else ++simulation_;
    }
    int sim() const { return simulation_; }
    int ui() const { return ui_; }
    int remaining() const { return frozen_; }
};
int main() {
    Clock c;
    assert(c.request(3));
    assert(c.request(0) && c.remaining()==3);
    for (int i=0;i<3;++i) c.step();
    assert(c.sim()==0 && c.ui()==3 && c.remaining()==0);
    c.step(); assert(c.sim()==1 && c.ui()==4);
    assert(c.request(2)); c.step();
    assert(c.request(4)); // 남은1에4를 더하지 않고4로 갱신
    for (int i=0;i<4;++i)c.step();
    assert(c.sim()==1 && c.remaining()==0);
    assert(!c.request(9) && !c.request(-1));
    assert(c.request(0));c.step();assert(c.sim()==2);
    std::cout<<"hit-stop clock tests passed\n";
}
